<?php $page_title='Newsletter';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['id'];$pdo->prepare("DELETE FROM newsletter_subscribers WHERE id=?")->execute([$id]);flash('success','Subscriber removed.');header('Location: newsletter.php');exit;}$rows=$pdo->query("SELECT * FROM newsletter_subscribers ORDER BY created_at DESC")->fetchAll();?>
<div class="page-head"><div><h1>Newsletter</h1><p><?=count($rows)?> subscribers · duplicate emails are prevented.</p></div></div><div class="panel"><div class="table-wrap"><table><tr><th>ID</th><th>Email</th><th>Subscribed</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['email'])?></td><td><?=date('M d, Y H:i',strtotime($r['created_at']))?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
